-- UST Campus Store case study (CSELEC1C). Practice data, not real sales.
\set ON_ERROR_STOP on
SET client_min_messages = warning;
-- Session 1. Creates the store's source system in schema src.
-- Every column is text, the way the extract arrived. Running this file again resets the source.
--   createdb campus_store
--   psql -d campus_store -f source/01_campus_store_source.sql

BEGIN;
DROP SCHEMA IF EXISTS src CASCADE;
CREATE SCHEMA src;

CREATE TABLE src.branches (
    branch_code text,
    branch_name text,
    branch_type text,
    building text,
    opened_on text
);
COPY src.branches (branch_code, branch_name, branch_type, building, opened_on) FROM stdin WITH (FORMAT csv);
